files.install-krea2.ps1:
# install-krea2.ps1
#
# Sets up the "Krea-2 Turbo" text-to-image service using the OFFICIAL Krea-2
# inference code (github.com/krea-ai/krea-2) -- no ComfyUI. It creates a CUDA
# venv, clones the repo, installs its deps, downloads the Turbo checkpoint, and
# pre-caches the Qwen3-VL-4B text encoder + Qwen-Image VAE. krea2_server.py then
# loads it and exposes POST /generate for oaiy-web.
#
# One-time cost is large: PyTorch (CUDA 12.8, for RTX 50-series/Blackwell) +
# ~24 GB Turbo checkpoint (bf16) + ~8 GB Qwen3-VL-4B encoder.
#
# Env: OAIY_BIN_DIR (= <dataDir>/bin), OAIY_HF_TOKEN (optional; needed if the
# krea/Krea-2-Turbo or Qwen repos require accepting a license / a token).

$ErrorActionPreference = 'Stop'
# Invoke-WebRequest's progress bar is slow and can stall in a piped context.
$ProgressPreference = 'SilentlyContinue'

if (-not $env:OAIY_BIN_DIR) {
    Write-Error 'OAIY_BIN_DIR is not set; this script expects to be invoked by the OAIY app/server.'
    exit 1
}

$dataDir = Split-Path $env:OAIY_BIN_DIR -Parent
$svcDir = Join-Path $dataDir 'services\krea2'
$repo = Join-Path $svcDir 'krea-2'
$venv = Join-Path $dataDir 'venvs\krea2'
$venvPy = Join-Path $venv 'Scripts\python.exe'
# The checkpoint lives under the central models dir (OAIY_MODELS_DIR, any drive). The shared
# Qwen3-VL encoder + VAE stay in the default HF cache (already central for HF models; moving
# them per-service forces a slow, flaky re-download).
$modelsDir = if ($env:OAIY_MODELS_DIR) { $env:OAIY_MODELS_DIR } else { Join-Path $dataDir 'models' }
$krea2Models = Join-Path $modelsDir 'krea2'
$ckptDir = Join-Path $krea2Models 'checkpoints'
$fetchZip = Join-Path $dataDir 'scripts\fetch_zip.py'
New-Item -ItemType Directory -Force -Path $svcDir, $ckptDir | Out-Null

# 1. Base Python (companion runtime first, then a system python).
$companionPy = Join-Path $dataDir 'python\python.exe'
$basePy = $null
if (Test-Path $companionPy) {
    $basePy = $companionPy
} else {
    foreach ($cand in @('python', 'py')) {
        try { $null = & $cand --version 2>&1; if ($LASTEXITCODE -eq 0) { $basePy = $cand; break } } catch {}
    }
}
if (-not $basePy) { Write-Error 'No Python found. Run "oaiy python install" (or install Python 3.11+).'; exit 1 }

# 2. venv
if (-not (Test-Path $venvPy)) {
    Write-Host "[install-krea2] creating venv at $venv"
    & $basePy -m venv $venv
    if ($LASTEXITCODE -ne 0) { Write-Error "venv creation failed"; exit 2 }
}

$git = Get-Command git -ErrorAction SilentlyContinue
# Validated krea-ai/krea-2 commit -- pin so an upstream model-layout change can't
# silently break the GGUF tensor-name mapping (krea2_gguf.py also asserts a match).
$krea2Commit = 'cf3c9102c924168699b90d97a2cb15059d761488'

# 3. Clone the official krea-2 inference repo, pinned to the validated commit. A
# leftover partial dir (from an interrupted clone/extract) would wedge every
# re-run -- git refuses a non-empty target and the zip rename would nest -- so
# clear it first.
if (-not (Test-Path (Join-Path $repo 'inference.py'))) {
    if (Test-Path $repo) { Remove-Item -Recurse -Force $repo }
    if ($git) {
        Write-Host "[install-krea2] fetching krea-ai/krea-2 @ $krea2Commit"
        & git init -q $repo
        & git -C $repo remote add origin https://github.com/krea-ai/krea-2
        & git -C $repo fetch --depth 1 -q origin $krea2Commit 2>$null
        if ($LASTEXITCODE -eq 0) { & git -C $repo checkout -q --detach FETCH_HEAD 2>$null }
        if ($LASTEXITCODE -ne 0) {
            Write-Warning "[install-krea2] could not fetch pinned $krea2Commit; cloning latest (loader verifies GGUF key match)"
            Remove-Item -Recurse -Force $repo -ErrorAction SilentlyContinue
            & git clone --depth 1 https://github.com/krea-ai/krea-2 $repo
        }
    } else {
        Write-Host "[install-krea2] git not found -- fetching krea-2 zip @ $krea2Commit"
        & $venvPy $fetchZip "https://github.com/krea-ai/krea-2/archive/$krea2Commit.zip" $svcDir
        $extracted = Join-Path $svcDir "krea-2-$krea2Commit"
        if (Test-Path $extracted) { Move-Item $extracted $repo } else { Write-Error "krea-2 zip did not contain krea-2-$krea2Commit"; exit 3 }
    }
}
if (-not (Test-Path (Join-Path $repo 'inference.py'))) { Write-Error 'krea-2 repo fetch failed'; exit 3 }

# 4. PyTorch cu128 (Blackwell) + the repo deps + the server deps.
Write-Host "[install-krea2] upgrading pip"
& $venvPy -m pip install --upgrade pip
Write-Host "[install-krea2] installing PyTorch cu128 (large, one-time)"
& $venvPy -m pip install torch torchvision --index-url https://download.pytorch.org/whl/cu128
if ($LASTEXITCODE -ne 0) { Write-Error "torch install failed"; exit 4 }
Write-Host "[install-krea2] installing krea-2 + server dependencies"
& $venvPy -m pip install 'transformers==4.57.1' 'diffusers>=0.32.0' safetensors pillow einops click accelerate gguf 'huggingface_hub[hf_transfer,hf_xet]' fastapi 'uvicorn[standard]' requests
if ($LASTEXITCODE -ne 0) { Write-Error "dependency install failed"; exit 5 }

# 5. Download the Turbo checkpoint (~24 GB) + pre-cache the encoder/VAE.
$env:HF_HUB_ENABLE_HF_TRANSFER = '1'
$env:KREA2_CKPT_DIR = $ckptDir
# Default to the Q4_K_M GGUF (~8 GB, dequantized at load by krea2_gguf.py). Set
# OAIY_KREA2_QUANT=bf16 for the full 24 GB checkpoint, or another GGUF tag
# (Q5_K_M, Q6_K, Q8_0, ...) for a different size/quality.
$quant = if ($env:OAIY_KREA2_QUANT) { $env:OAIY_KREA2_QUANT } else { 'Q4_K_M' }
$env:KREA2_QUANT = $quant
if ($quant -eq 'bf16') {
    Write-Host "[install-krea2] downloading turbo.safetensors (bf16, ~24 GB) -- this takes a while"
    & $venvPy -c "import os; from huggingface_hub import hf_hub_download; hf_hub_download('krea/Krea-2-Turbo','turbo.safetensors', local_dir=os.environ['KREA2_CKPT_DIR'], token=os.environ.get('OAIY_HF_TOKEN') or None)"
} else {
    Write-Host "[install-krea2] downloading krea2_turbo-$quant.gguf (~8 GB)"
    & $venvPy -c "import os; from huggingface_hub import hf_hub_download; hf_hub_download('vantagewithai/Krea-2-Turbo-GGUF', 'krea2_turbo-' + os.environ['KREA2_QUANT'] + '.gguf', local_dir=os.environ['KREA2_CKPT_DIR'], token=os.environ.get('OAIY_HF_TOKEN') or None)"
}
if ($LASTEXITCODE -ne 0) { Write-Error 'checkpoint download failed (if gated, accept the license on HuggingFace and set OAIY_HF_TOKEN).'; exit 6 }
# Keep exactly one checkpoint so the server never has to choose between a GGUF and
# a bf16 leftover (also reclaims the other variant's disk). Runs only after the
# new file landed, so the dir is never left empty.
$keep = if ($quant -eq 'bf16') { 'turbo.safetensors' } else { "krea2_turbo-$quant.gguf" }
Get-ChildItem $ckptDir -File -ErrorAction SilentlyContinue | Where-Object { ($_.Extension -in '.gguf', '.safetensors') -and ($_.Name -ne $keep) } | Remove-Item -Force -ErrorAction SilentlyContinue

Write-Host "[install-krea2] pre-caching Qwen3-VL-4B encoder + Qwen-Image VAE"
& $venvPy -c "import os; from huggingface_hub import snapshot_download; tok=os.environ.get('OAIY_HF_TOKEN') or None; snapshot_download('Qwen/Qwen3-VL-4B-Instruct', token=tok); snapshot_download('Qwen/Qwen-Image', allow_patterns=['vae/*'], token=tok)"
if ($LASTEXITCODE -ne 0) { Write-Warning '[install-krea2] could not pre-cache the encoder/VAE; they will download on first start.' }

Write-Host "[install-krea2] done. Start the 'Krea-2 Turbo' service, then POST /generate {prompt}."
